/// <summary>
/// Kleber customer address predictive search request contract
/// </summary>
[DataContractAttribute]
class METKleberCustAddressPredictiveSearchRequestContract
{
    LogisticsAddressStreet addressLine;
    str requestId, departmentCode, requestLimit;

}

Method.Source:
/// <summary>
/// Get or set Address line 
/// </summary>
/// <param name = "_addressLine">Address line</param>
/// <returns>Address line</returns>
[DataMemberAttribute("AddressLine")]
public LogisticsAddressStreet parmAddressLine(str _addressLine = addressLine)
{
    addressLine = _addressLine;
    return addressLine;
}

/// <summary>
/// Get or set RequestId
/// </summary>
/// <param name = "_requestId">requestId</param>
/// <returns>requestId</returns>
[DataMemberAttribute("RequestId")]
public str parmRequestId(str _requestId = requestId)
{
    requestId = _requestId;
    return requestId;
}

/// <summary>
/// Get or set department code
/// </summary>
/// <param name = "_departmentCode">Department code</param>
/// <returns>Department code</returns>
[DataMemberAttribute("DepartmentCode")]
public str parmDepartmentCode(str _departmentCode = departmentCode)
{
    departmentCode = _departmentCode;
    return departmentCode;
}

/// <summary>
/// Get or set RequestLimit
/// </summary>
/// <param name = "_requestLimit">RequestLimit</param>
/// <returns>RequestLimit</returns>
[DataMemberAttribute("RequestLimit")]
public str parmRequestLimit(str _requestLimit = requestLimit)
{
    requestLimit = _requestLimit;
    return requestLimit;
}
